using Amazon.SimpleSystemsManagement;

var ssmClient = new AmazonSimpleSystemsManagementClient(RegionEndpoint.USEast1);

var request = new GetParameterRequest
{
    Name = "/aspnet/appsettings/FeatureFlags:EnableNewUi",
    WithDecryption = true
};

var response = await ssmClient.GetParameterAsync(request);
string featureFlag = response.Parameter.Value;
Console.WriteLine($"New UI enabled: {featureFlag}");
